import {equalityFamilies} from './equality-desk-content.mjs';
import {exprText,normalEquation,formatNumber,validEqualityCheck,validEqualityProbe,validEqualityKeep,equalityView,startEquality,resumeEquality,editEquality,pageEquality,lineEquality,helpEquality,probeEquality,checkEquality,keepEquality,removeEquality} from './equality-desk-core.mjs';
import {stopSpeech} from './play-media.mjs';

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const pages=['Meet the rules','Try numbers','Explain why','Make a claim'];
const equation=s=>`${exprText(s.left)} = ${exprText(s.right)}`;
const own=(x,k)=>Object.hasOwn(x,k);
const badRecord=(label)=>`<p class="equality-retained" data-equality-unreadable>${esc(label)} is retained exactly in your notebook download but cannot be read here.</p>`;
const choiceLabel=(s,id)=>s.choices.find(c=>c.id===id)?.label||id||'not chosen';
const support=(help,line)=>`Proof support opened through line ${Number(line)+1}; requested help: ${help.length?help.map(esc).join(', '):'none'}. All shown teaching still supports this practice.`;
function rules(s){return `<div class="equality-rules" data-equality-equation aria-label="The two rules to compare"><div class="equality-left"><span>Left rule</span><strong>${esc(exprText(s.left))}</strong></div><span class="equality-equals" aria-hidden="true">=</span><div class="equality-right"><span>Right rule</span><strong>${esc(exprText(s.right))}</strong></div></div><p class="equality-domain">Any real number is allowed for x, including positive and negative numbers, zero, and fractions. Which values make these rules equal?</p>`;}
function chooser(w){return `<section class="equality-chooser"><h2>Choose a new investigation</h2><p>Keep exploring the same idea with different numbers. Earlier visits stay in your notebook.</p><label for="equality-family">Rules to investigate<select id="equality-family" data-equality-family>${equalityFamilies.map(f=>`<option value="${esc(f.id)}"${w?.source.family===f.id?' selected':''}>${esc(f.title)}</option>`).join('')}</select></label>${btn('data-equality-start','Start a new visit',true)}</section>`;}
function visitList(v){if(!v.visits.length)return '';return `<details class="equality-visits" data-equality-panel="visits"><summary>Your visits (${v.visits.length})</summary><div class="equality-actions">${v.visits.map(x=>x.readable?btn(`data-equality-resume="${esc(x.id)}" aria-pressed="${v.current===x.id}"`,x.title||x.id):badRecord(`Visit ${x.id}`)).join('')}</div></details>`;}
function meet(w){const s=w.source;return `<h2 id="equality-heading" tabindex="-1">When do the rules agree?</h2><p class="equality-story">${esc(s.story)}</p>${s.teaching.map(t=>`<p>${esc(t)}</p>`).join('')}<aside class="equality-example"><h3>A different worked example</h3><p>${esc(s.help.example)}</p></aside><p>These are rules for numbers, not objects on a balance. A negative number is allowed here. Try a number, or open the reasoning whenever you like.</p>`;}
function probeCard(p,s,latest=false){const sub=(e)=>exprText(e).replaceAll('x',`(${p.raw})`);return `<article class="equality-probe"${latest?' data-equality-probe-result tabindex="-1"':''}><h3>Testing x = ${esc(p.raw)}</h3><table><caption>The same input in both rules</caption><thead><tr><th scope="col">Left rule</th><th scope="col">Right rule</th></tr></thead><tbody><tr><td>${esc(sub(s.left))}</td><td>${esc(sub(s.right))}</td></tr><tr><td><strong>${esc(formatNumber(p.left))}</strong></td><td><strong>${esc(formatNumber(p.right))}</strong></td></tr></tbody></table><p class="equality-test-verdict">${p.equal?'Equal for this input. This number is a solution.':'Different for this input. This number is not a solution.'}</p></article>`;}
function tests(w){const readable=w.tests.filter(validEqualityProbe),last=w.tests.at(-1);return `<h2 id="equality-heading" tabindex="-1">Try the same number in both rules</h2><p>A matching test shows that the number you tested is a solution. It cannot tell you whether other numbers work too. Even many matching tests cannot show that every number works. If your tests do not match, there could still be a solution you have not tried.</p><label for="equality-test-input">Number to use for x<input id="equality-test-input" data-equality-field="input" type="text" inputmode="text" autocomplete="off" spellcheck="false" maxlength="40" value="${esc(w.input)}" aria-describedby="equality-number-format"></label><p id="equality-number-format" class="equality-small">Use a number such as −2 (type -2), 0.5, or 3/2. Enter a number, not an expression.</p><div class="equality-actions">${btn('data-equality-probe','Test this number',true)}${[-2,0,2].map(n=>btn(`data-equality-preset="${n}"`,`Test ${n}`)).join('')}</div>${w.tests.length>=12?'<p>The twelve saved tests are kept. You can still reason, make a claim, or start another visit.</p>':''}${last===undefined?'':validEqualityProbe(last)?probeCard(last,w.source,true):badRecord('The latest test')}${w.tests.length>1?`<details data-equality-panel="tests"><summary>Earlier tests (${w.tests.length-1})</summary>${w.tests.slice(0,-1).map((p,i)=>validEqualityProbe(p)?probeCard(p,w.source):badRecord(`Test ${i+1}`)).join('')}</details>`:''}${readable.length&&readable.every(t=>!t.equal)?'<p data-equality-finite-tests>None of these tested numbers worked. That does not prove that no number works. Look at the reasoning next.</p>':''}`;}
function proof(w){const s=w.source;return `<h2 id="equality-heading" tabindex="-1">Make changes that keep the same solutions</h2><p>Opening a line is help. We change both sides in a way that keeps exactly the same solutions. We never divide by zero.</p><ol class="equality-proof" data-equality-proof>${s.steps.slice(0,w.line+1).map((step,i)=>`<li${i===w.line?' class="equality-current-line"':''}><p class="equality-proof-equation">${esc(step.operation==='start'?equation(s):normalEquation(step))}</p><p>${esc(step.reason)}</p></li>`).join('')}</ol><div class="equality-actions">${btn(`data-equality-line="${w.line-1}"${w.line===0?' disabled':''}`,'Previous line')}${btn(`data-equality-line="${w.line+1}"${w.line+1>=s.steps.length?' disabled':''}`,'Show next line',true)}</div><p class="equality-small">Showing line ${w.line+1} of ${s.steps.length}. Going back preserves which help you have already opened.</p><aside class="equality-talk"><h3>Tell someone why</h3><p>What did the change do to the left side? What did it do to the right? Could it change which numbers work?</p></aside>`;}
function checkRecord(r,label,currentSource){const other=JSON.stringify(r.source)!==JSON.stringify(currentSource);return `<article class="equality-checked" data-equality-saved-check="${esc(label)}"><h3>${esc(label)}</h3>${other?'<p class="equality-retained">This response belongs to another frozen source. It does not answer the current equation.</p>':''}<p class="equality-historical-equation">${esc(equation(r.source))}</p><p>Claim: <strong>${esc(choiceLabel(r.source,r.raw.choice))}</strong>${r.raw.choice==='one'?` · x = ${esc(r.raw.answer)}`:''}.</p><p data-equality-feedback>${esc(r.feedback)}</p>${r.raw.note?`<p>Your explanation: ${esc(r.raw.note)}</p>`:''}<p class="equality-small">${support(r.helpBefore,r.seenLineBefore)} ${r.testsBefore.length} tests were already saved before this check.</p></article>`;}
function checkedHistory(w){const latest=w.checks.at(-1);return `<section class="equality-history"><h2>Checks kept as answered</h2>${latest===undefined?'<p>No checked claim yet. You can change your claim at any time.</p>':validEqualityCheck(latest)?checkRecord(latest,'Latest check',w.source):badRecord('The latest check')}${own(w,'firstCheck')?`<details data-equality-panel="first"><summary>First check · kept as answered</summary>${validEqualityCheck(w.firstCheck)?checkRecord(w.firstCheck,'First check',w.source):badRecord('The first check')}</details>`:''}${w.checks.some(x=>!validEqualityCheck(x))?'<p class="equality-retained">Unreadable check entries stay exact in your notebook download. Healthy checks remain available.</p>':''}<p class="equality-small">${w.checks.length} of twelve checks retained. Later editing never changes an earlier result.</p></section>`;}
function keptRecord(k,label,currentSource){return `<article class="equality-kept"><h3>${esc(label)}</h3>${JSON.stringify(k.source)!==JSON.stringify(currentSource)?'<p class="equality-retained">This kept writing has its own frozen equation.</p>':''}<p class="equality-historical-equation">${esc(equation(k.source))}</p><p>Claim: ${esc(choiceLabel(k.source,k.choice)||'not chosen')}${k.choice==='one'?` · x = ${esc(k.answer)||'not given'}`:''}.</p>${k.note?`<p>Your explanation: ${esc(k.note)}</p>`:'<p>No written explanation.</p>'}<p class="equality-small">${support(k.help,k.seenLine)} This is a kept visit, not a completion or mastery label.</p>${k.latestCheck===null||k.latestCheck===undefined?'<p>No checked claim was captured with this keep.</p>':validEqualityCheck(k.latestCheck)?checkRecord(k.latestCheck,'Check captured when kept',k.source):badRecord('The check captured when kept')}</article>`;}
function keptHistory(w){return `<details data-equality-panel="kept"><summary>Kept writing · first and latest</summary>${['firstKept','kept'].map((key,i)=>own(w,key)?validEqualityKeep(w[key])?keptRecord(w[key],i===0?'First kept visit':'Latest kept visit',w.source):badRecord(i===0?'The first kept visit':'The latest kept visit'):'').join('')||'<p>No kept writing yet. An unfinished visit can be worth keeping.</p>'}</details>`;}
function help(w){return `<aside class="equality-help"><h3>Help is always available</h3><div class="equality-actions">${btn('data-equality-help="hint"','Open a hint')}${btn('data-equality-help="example"','Open a different example')}</div>${w.help.includes('hint')?`<section><h4>A hint</h4><p>${esc(w.source.help.hint)}</p></section>`:''}${w.help.includes('example')?`<section><h4>A different worked example</h4><p>${esc(w.source.help.example)}</p></section>`:''}</aside>`;}
function claim(w){return `<h2 id="equality-heading" tabindex="-1">What can you say about all the solutions?</h2><p>Choose a claim. If exactly one number works, give that number. You can check, revise, or go back to the reasoning.</p><div class="equality-choices" role="group" aria-label="How many real-number solutions?">${w.source.choices.map(c=>btn(`data-equality-choice="${esc(c.id)}" aria-pressed="${w.choice===c.id}"`,c.label)).join('')}</div>${w.choice==='one'?`<label for="equality-answer">The one number is x =<input id="equality-answer" data-equality-field="answer" type="text" inputmode="text" autocomplete="off" spellcheck="false" maxlength="40" value="${esc(w.answer)}"></label>`:''}<label for="equality-note">Why do you think so? (optional)<textarea id="equality-note" data-equality-field="note" rows="3" maxlength="1200">
${esc(w.note)}</textarea></label><div class="equality-actions">${btn('data-equality-check','Check my claim',true)}${btn('data-equality-keep','Keep this visit')}</div>${help(w)}<div id="equality-result" tabindex="-1">${checkedHistory(w)}</div>${keptHistory(w)}`;}
function space(v){return `<details class="equality-space" data-equality-panel="space"><summary>Download your notebook or make room</summary><p>Up to 24 visits and twelve tests and checks per visit are retained. Nothing is automatically removed. Download your notebook before removing anything you want to keep.</p><a class="secondary" href="#notes">Open notes and download</a><label for="equality-remove-choice">Visit to remove<select id="equality-remove-choice" data-equality-remove-choice>${v.visits.filter(x=>x.readable).map(x=>`<option value="${esc(x.id)}">${esc(x.title||x.id)}</option>`).join('')}</select></label>${btn('data-equality-delete','Remove selected visit')}</details>`;}
export function equalityEntry(){return '<aside class="equality-entry"><h2>The Equality Desk</h2><p>Two rules, one question: when do they agree? Test numbers, then find a reason that holds beyond your tests.</p><a class="secondary" href="#learn/math/equality">Open the Equality Desk</a></aside>';}
export function equalityRefusal(){return '<section class="equality-page" data-equality-root><h1>The Equality Desk</h1><h2 id="equality-heading" tabindex="-1">This page could not be opened safely</h2><p>Your earlier work is unchanged. The notebook could not retain the support shown by this page. You can download your notes or choose another destination.</p><a class="secondary" href="#notes">Open notes</a><a class="secondary" href="#pathways/math">Other math explorations</a><p id="equality-status" role="status" tabindex="-1"></p></section>';}
export function equalityPage(state){const v=equalityView(state),w=v.work,head='<section class="equality-page" data-equality-root><header class="equality-header"><a class="secondary" href="#learn/math">Back to signed rates and equations</a><h1>The Equality Desk</h1><p>Compare two rules. Find what makes them agree.</p></header>';if(v.status==='unavailable')return head+'<h2 id="equality-heading" tabindex="-1">Earlier work is retained</h2><p>This version cannot edit that saved format. Your exact records stay in the notebook download, and every other destination stays open.</p><a class="secondary" href="#notes">Open notes</a><p id="equality-status" role="status" tabindex="-1"></p></section>';
 const visitUI=visitList(v);if(!w)return head+`<section class="equality-intro"><h2 id="equality-heading" tabindex="-1">The surveyors need a second look</h2><p>Two surveyors have written rules for the same mark. Could the rules agree for one number, for every number, or for no number? Bring your curiosity and choose a pair to investigate.</p>${v.status==='unreadable'?badRecord('The selected visit'):''}</section>${chooser(null)}${visitUI}<p id="equality-status" role="status" aria-live="polite" tabindex="-1"></p><div data-equality-pending-actions hidden><p>Some visible words have not been saved. Restore the last saved words to continue.</p>${btn('data-equality-restore','Restore saved words')}</div><footer><a class="secondary" href="#pathways/math">Other math explorations</a><a class="secondary" href="#notes">Grown-up notes</a></footer></section>`;
 return head+`<section class="equality-sticky"><p class="equality-visit-title">${esc(w.source.title)}</p>${rules(w.source)}<nav class="equality-pages" aria-label="Equality Desk pages">${pages.map((name,i)=>btn(`data-equality-page="${i}" aria-current="${w.page===i?'step':'false'}"`,name)).join('')}</nav></section><section class="equality-turn">${[meet,tests,proof,claim][w.page](w)}</section><nav class="equality-page-arrows" aria-label="Previous and next page">${w.page>0?btn(`data-equality-page="${w.page-1}"`,`Previous: ${pages[w.page-1]}`):''}${w.page<3?btn(`data-equality-page="${w.page+1}"`,`Next: ${pages[w.page+1]}`,true):''}</nav><p id="equality-status" role="status" aria-live="polite" tabindex="-1"></p><div data-equality-pending-actions hidden><p>Some visible words have not been saved. Edit the marked field to try again, or copy those words and deliberately restore the last saved words.</p>${btn('data-equality-restore','Restore saved words')}</div>${chooser(w)}${visitUI}${space(v)}<details class="equality-grownups" data-equality-panel="grownups"><summary>Grown-ups · what this practice shows</summary><p>Numerical tests are observations. Equivalent algebraic steps explain why exactly one number, no number, or every real number works. A finite set of matching tests cannot establish an identity.</p><p>All of this is supported practice. Proof lines, optional help and earlier tests are kept separately with each response. These records do not establish independent fluency, mastery, or placement.</p><p>The same idea returns with translated numbers. All families and pages stay open. The bound on typed numbers is an input limit; x still ranges over all real numbers in the mathematics.</p></details><footer><a class="secondary" href="#pathways/math">Other math explorations</a><a class="secondary" href="#notes">Grown-up notes</a></footer></section>`;
}
export function equalityNotes(state){if(!own(state,'equalityDesk'))return '';const v=equalityView(state);return `<details class="panel equality-notes"><summary>Equality Desk · supported investigations</summary><p>Frozen sources, raw writing, tests, original first/latest checks and kept writing stay separate. All shown teaching supports these tasks; these are not mastery or placement records.</p>${v.status==='unavailable'?'<p>An earlier format is retained unchanged.</p>':v.visits.map(x=>x.readable?`<p>${esc(x.title||x.id)}: ${v.root.visits[x.id].tests.length} tests; ${v.root.visits[x.id].checks.length} checks. Proof help opened through line ${v.root.visits[x.id].seenLine+1}. ${own(v.root.visits[x.id],'kept')?'Kept writing retained.':'No kept writing yet.'}</p>`:badRecord(`Visit ${x.id}`)).join('')}<p>Unreadable or future records remain exact in the raw notebook download; readable sibling visits remain open. Original outcomes are never regraded.</p><details><summary>Exact saved sources and work</summary><pre>${esc(JSON.stringify(state.equalityDesk,null,2))}</pre></details></details>`;}

let removeGuards=()=>{},pendingNavigation=()=>false;
export const guardEqualityNavigation=()=>pendingNavigation();
export function bindEquality(state,{save,render,focus,canExport,exposeFacts,explorerId,isActive}={}){
 removeGuards();removeGuards=()=>{};const root=document.querySelector('[data-equality-root]');if(!root)return;
 const owner=explorerId?.(),route=location.hash,o={canExport,exposeFacts},dirty=new Set();
 const live=el=>root.isConnected&&el?.isConnected&&root.contains(el)&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive());
 const say=(text,take=false)=>{const el=root.querySelector('#equality-status');if(el){el.textContent=text;if(take)el.focus();}};
 const pendingMessage='Your visible words have not been saved. Edit the marked field to try again, or copy them and choose Restore saved words before continuing.';
 const pendingUI=()=>{const el=root.querySelector('[data-equality-pending-actions]');if(el)el.hidden=!dirty.size;};
 const redraw=(message='',target='#equality-heading')=>{const panels=new Map([...root.querySelectorAll('details[data-equality-panel]')].map(n=>[n.dataset.equalityPanel,n.open]));stopSpeech();save?.();render?.();const next=document.querySelector('[data-equality-root]');next?.querySelectorAll('details[data-equality-panel]').forEach(n=>{if(panels.has(n.dataset.equalityPanel))n.open=panels.get(n.dataset.equalityPanel);});const status=next?.querySelector('#equality-status');if(status)status.textContent=message;const el=next?.querySelector(target);if(el)el.focus();else focus?.('#equality-heading');};
 const fail=()=>say('This change could not be kept safely. Earlier work is unchanged. The visit or notebook may be full. Download your notes before making room, or choose another investigation.',true);
 const act=(el,fn,message='',target='#equality-heading')=>{if(!live(el))return;if(dirty.size){say(pendingMessage,true);return;}const r=fn();if(!r)return fail();if(r.recorded===false){say(r.feedback,true);return;}redraw(message,target);};
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 on('[data-equality-start]',el=>act(el,()=>startEquality(state,root.querySelector('[data-equality-family]')?.value,o),'New rules are open. Earlier visits are retained.'));
 on('[data-equality-resume]',el=>act(el,()=>resumeEquality(state,el.dataset.equalityResume,o),'Resumed the original rules and work.'));
 on('[data-equality-page]',el=>act(el,()=>pageEquality(state,Number(el.dataset.equalityPage),o)));
 on('[data-equality-line]',el=>act(el,()=>lineEquality(state,Number(el.dataset.equalityLine),o),'Reasoning support saved before showing it.','#equality-heading'));
 on('[data-equality-choice]',el=>act(el,()=>editEquality(state,'choice',el.dataset.equalityChoice,o),'Claim saved. You can still change it.',`[data-equality-choice="${el.dataset.equalityChoice}"]`));
 const cappedProbe=raw=>equalityView(state).work?.tests.length>=12?{recorded:false,feedback:'This visit already retains twelve tests. Earlier tests stay unchanged. You can edit your writing, open the reasoning, make a claim, or choose a new investigation to save more tests.'}:probeEquality(state,raw,o);
 on('[data-equality-probe]',el=>act(el,()=>cappedProbe(undefined),'Test saved. This result concerns just the number you tested.','[data-equality-probe-result]'));
 on('[data-equality-preset]',el=>act(el,()=>cappedProbe(el.dataset.equalityPreset),'Test saved. This result concerns just the number you tested.','[data-equality-probe-result]'));
 on('[data-equality-help]',el=>act(el,()=>helpEquality(state,el.dataset.equalityHelp,o),'Help opened and recorded.',`[data-equality-help="${el.dataset.equalityHelp}"]`));
 on('[data-equality-check]',el=>act(el,()=>equalityView(state).work?.checks.length>=12?{recorded:false,feedback:'This visit already retains twelve checks. Earlier responses stay unchanged. You can still edit and keep your writing, revisit any page, or choose a new investigation to save more checks.'}:checkEquality(state,o),'Checked claim kept as answered. You can revise it.','#equality-result'));
 on('[data-equality-keep]',el=>act(el,()=>keepEquality(state,o),'Visit kept. Later edits leave earlier kept writing unchanged.','#equality-result'));
 on('[data-equality-delete]',el=>{if(dirty.size)return say(pendingMessage,true);const id=root.querySelector('[data-equality-remove-choice]')?.value;if(!id)return say('Choose a readable visit to remove.',true);const visit=equalityView(state).visits.find(x=>x.id===id);if(!window.confirm(`Remove ${visit?.title||id} and its original rules, tests, checks and kept writing? Download notes first if you want to retain them.`))return;if(!live(el))return;act(el,()=>removeEquality(state,id,true,o),'Selected visit removed. Other visits remain available.');});
 root.querySelectorAll('[data-equality-field]').forEach(el=>el.addEventListener('input',()=>{if(!live(el))return;const key=el.dataset.equalityField;if(!editEquality(state,key,el.value,o)){dirty.add(key);el.setAttribute('aria-invalid','true');pendingUI();say(pendingMessage);return;}dirty.delete(key);el.removeAttribute('aria-invalid');save?.();pendingUI();say(dirty.size?pendingMessage:'Words saved.');}));
 on('[data-equality-restore]',el=>{if(!live(el)||!window.confirm('Discard the visible unsaved edits and restore this page’s last saved words? Earlier saved work stays unchanged.'))return;dirty.clear();redraw('Last saved words restored.','#equality-heading');});
 const guard=e=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(!root.isConnected||location.hash!==route||explorerId?.()!==owner||!dirty.size)return;const target=e.target;if(target?.closest?.('[data-equality-field],[data-equality-restore]'))return;if(target?.closest?.('button,a,input,select,summary')){e.preventDefault();e.stopImmediatePropagation();say(pendingMessage);}};
 pendingNavigation=()=>{if(!root.isConnected||explorerId?.()!==owner||!dirty.size)return false;history.replaceState(null,'',route);say(pendingMessage);return true;};
 const beforeLeave=e=>{if(dirty.size&&root.isConnected){e.preventDefault();e.returnValue='';}};
 document.addEventListener('click',guard,true);document.addEventListener('keydown',guard,true);window.addEventListener('beforeunload',beforeLeave);
 removeGuards=()=>{document.removeEventListener('click',guard,true);document.removeEventListener('keydown',guard,true);window.removeEventListener('beforeunload',beforeLeave);pendingNavigation=()=>false;};
}
